mapper.select:
SELECT b.id, b.title, b.content, b.author_id, u.username as author_name, u.avatar_url as author_avatar, b.status, b.like_count, b.view_count, b.category_id, c.name as category_name, b.created_at, b.updated_at FROM blogs b LEFT JOIN users u ON b.author_id = u.user_id LEFT JOIN categories c ON b.category_id = c.id
b.status = 1
AND b.title LIKE concat('%', #{keyword}, '%')
AND b.category_id = #{categoryId}
ORDER BY b.view_count DESC, b.created_at DESC ORDER BY b.like_count DESC, b.created_at DESC ORDER BY b.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM blogs b
WHERE b.author_id = #{authorId}

mapper.update:
UPDATE blogs
title = #{title}, content = #{content}, status = #{status}, category_id = #{categoryId}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT COUNT(1)
FROM user_favorites
WHERE user_id = #{userId}

SELECT COUNT(1) FROM blog_views
WHERE blog_id = #{blogId}
  AND ip_address = #{ipAddress}
  AND viewed_at >= CURRENT_DATE

SELECT COUNT(1) FROM blog_views
WHERE blog_id = #{blogId}
  AND user_id = #{userId}
  AND viewed_at >= CURRENT_DATE

SELECT u.user_id, u.username, u.avatar_url, bl.created_at as interacted_at
FROM blog_likes bl
JOIN users u ON bl.user_id = u.user_id
WHERE bl.blog_id = #{blogId}
ORDER BY bl.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT u.user_id, u.username, u.avatar_url, uf.created_at as interacted_at
FROM user_favorites uf
JOIN users u ON uf.user_id = u.user_id
WHERE uf.blog_id = #{blogId}
ORDER BY uf.created_at DESC
LIMIT #{limit} OFFSET #{offset}
